namespace convex {
namespace asio = boost::asio; namespace beast = boost::beast; namespace websocket = beast::websocket; namespace ssl = asio::ssl; using tcp = asio::ip::tcp;
static constexpr const char* zero_timestamp = "AAAAAAAAAAA=";
static std::string live_url(std::string url) { auto where = url.find("://"); if (where == std::string::npos) throw Error("invalid Convex deployment URL"); url.replace(0, where, url.substr(0, where) == "https" ? "wss" : "ws"); auto slash = url.find('/', where + 3); if (slash == std::string::npos) return url + "/api/sync"; while (!url.empty() && url.back() == '/') url.pop_back(); return url + "/api/sync"; }
static void split(const std::string& url, std::string& host, std::string& port, std::string& target) { auto start = url.find("://") + 3, slash = url.find('/', start); auto authority = url.substr(start, slash - start); auto colon = authority.rfind(':'); host = colon == std::string::npos ? authority : authority.substr(0, colon); port = colon == std::string::npos ? (url.rfind("wss://", 0) == 0 ? "443" : "80") : authority.substr(colon + 1); target = slash == std::string::npos ? "/api/sync" : url.substr(slash); }

struct Subscription::State : std::enable_shared_from_this<Subscription::State> {
  enum class Command { none, debug_disconnect, close };
  struct IntentionalDisconnect {};
  std::string url, path; Json args; std::mutex mutex; std::condition_variable cv; std::deque<Update> queue; bool stopped = false; bool connected = false; bool command_done = false; Command command = Command::none; unsigned connection_count = 0; std::thread worker;
  State(std::string u, std::string p, Json a) : url(live_url(std::move(u))), path(std::move(p)), args(std::move(a)) {}
  void push(Update update) { std::lock_guard lock(mutex); if (stopped) return; if (queue.size() == 16) queue.pop_front(); queue.push_back(std::move(update)); cv.notify_one(); }
  void run() { unsigned attempts = 0; while (true) { { std::lock_guard lock(mutex); if (stopped) return; } try { session(attempts); } catch (const IntentionalDisconnect&) { } catch (const ProtocolError& error) { push({Json(), {}, error.what(), Json(), "ProtocolError"}); } catch (const std::exception& error) { push({Json(), {}, std::string("Live transport: ") + error.what(), Json(), "TransportError"}); } { std::unique_lock lock(mutex); if (stopped) return; cv.wait_for(lock, std::chrono::milliseconds(std::min(15000u, 100u << std::min(attempts++, 7u))), [&]{ return stopped; }); } } }
  static std::string session_id() { std::random_device rd; std::mt19937_64 rng(rd()); char out[37]; std::snprintf(out, sizeof out, "%08x-%04x-4%03x-8%03x-%012llx", static_cast<unsigned>(rng()), static_cast<unsigned>(rng() & 0xffff), static_cast<unsigned>(rng() & 0xfff), static_cast<unsigned>(rng() & 0xfff), static_cast<unsigned long long>(rng() & 0xffffffffffffULL)); return out; }
  template <typename Stream> void exchange(Stream& ws, asio::io_context& io, unsigned& attempts) { struct Clear { State* state; ~Clear() { std::lock_guard lock(state->mutex); state->connected = false; state->command_done = true; state->cv.notify_all(); } } clear{this}; unsigned count; { std::lock_guard lock(mutex); count = connection_count++; connected = true; command_done = false; } Json connect{{"type","Connect"},{"sessionId",session_id()},{"connectionCount",count},{"lastCloseReason",count ? "NetworkError" : "InitialConnect"},{"maxObservedTimestamp",zero_timestamp},{"clientTs",0}}; ws.write(asio::buffer(connect.dump())); Json modify{{"type","ModifyQuerySet"},{"baseVersion",0},{"newVersion",1},{"modifications",Json::array({{{"type","Add"},{"queryId",0},{"udfPath",path},{"args",Json::array({args})}}})}}; ws.write(asio::buffer(modify.dump())); Json version{{"querySet",0},{"identity",0},{"ts",zero_timestamp}}; for (;;) { beast::flat_buffer buffer; beast::error_code read_error; bool read_done = false; ws.async_read(buffer, [&](beast::error_code error, std::size_t) { read_error = error; read_done = true; }); while (!read_done) { Command pending; { std::lock_guard lock(mutex); pending = command; command = Command::none; } if (pending != Command::none) { beast::error_code ignored; if (pending == Command::close) { Json remove{{"type","ModifyQuerySet"},{"baseVersion",1},{"newVersion",2},{"modifications",Json::array({{{"type","Remove"},{"queryId",0}}})}}; ws.write(asio::buffer(remove.dump()), ignored); } auto& socket = beast::get_lowest_layer(ws).socket(); socket.shutdown(tcp::socket::shutdown_both, ignored); socket.close(ignored); io.restart(); io.run_for(std::chrono::milliseconds(100)); throw IntentionalDisconnect{}; } io.restart(); io.run_for(std::chrono::milliseconds(50)); } if (read_error) throw boost::system::system_error(read_error); Json message; try { message = Json::parse(beast::buffers_to_string(buffer.data())); } catch (const std::exception& error) { throw ProtocolError(std::string("decode Live message: ") + error.what()); } if (message.value("type", "") != "Transition") { if (message.value("type", "") == "Ping") { attempts = 0; continue; } throw ProtocolError("unexpected Live server message"); } if (message.value("startVersion", Json::object()) != version) throw ProtocolError("Live transition version mismatch"); for (const auto& change : message.value("modifications", Json::array())) { if (change.value("queryId", -1) != 0) continue; if (change.value("type", "") == "QueryUpdated") push({change.at("value"), change.value("logLines", std::vector<std::string>{}), "", Json(), ""}); else if (change.value("type", "") == "QueryFailed") push({Json(), change.value("logLines", std::vector<std::string>{}), change.value("errorMessage", "Live query failed"), change.value("errorData", Json()), "FunctionError"}); else if (change.value("type", "") != "QueryRemoved") throw ProtocolError("unknown Live transition modification"); } version = message.at("endVersion"); attempts = 0; } }
  void session(unsigned& attempts) { std::string host, port, target; split(url, host, port, target); asio::io_context io; tcp::resolver resolver(io); if (url.rfind("wss://", 0) == 0) { ssl::context ctx(ssl::context::tls_client); ctx.set_default_verify_paths(); ctx.set_verify_mode(ssl::verify_peer); beast::ssl_stream<beast::tcp_stream> tls(io, ctx); tls.set_verify_callback(ssl::host_name_verification(host)); if (!SSL_set_tlsext_host_name(tls.native_handle(), host.c_str())) throw Error("configure Live TLS server name"); beast::get_lowest_layer(tls).connect(resolver.resolve(host, port)); tls.handshake(ssl::stream_base::client); websocket::stream<beast::ssl_stream<beast::tcp_stream>> ws(std::move(tls)); ws.set_option(websocket::stream_base::timeout::suggested(beast::role_type::client)); ws.handshake(host, target); attempts = 0; exchange(ws, io, attempts); } else { beast::tcp_stream tcp_stream(io); tcp_stream.connect(resolver.resolve(host, port)); websocket::stream<beast::tcp_stream> ws(std::move(tcp_stream)); ws.set_option(websocket::stream_base::timeout::suggested(beast::role_type::client)); ws.handshake(host, target); attempts = 0; exchange(ws, io, attempts); } }
};
Subscription::Subscription(std::string url, std::string path, Json args) : state_(std::make_shared<State>(std::move(url), std::move(path), std::move(args))) { state_->worker = std::thread([state = state_] { state->run(); }); }
Subscription::~Subscription() { close(); }
std::optional<Update> Subscription::next_update(int timeout_ms) { std::unique_lock lock(state_->mutex); if (!state_->cv.wait_for(lock, std::chrono::milliseconds(timeout_ms), [&]{ return state_->stopped || !state_->queue.empty(); })) return std::nullopt; if (state_->queue.empty()) return std::nullopt; auto update = std::move(state_->queue.front()); state_->queue.pop_front(); return update; }
void Subscription::close() { if (!state_) return; { std::unique_lock lock(state_->mutex); if (state_->stopped) { lock.unlock(); if (state_->worker.joinable()) state_->worker.join(); return; } state_->stopped = true; if (state_->connected) { state_->command = State::Command::close; state_->command_done = false; state_->cv.wait_for(lock, std::chrono::seconds(2), [&]{ return state_->command_done; }); } state_->cv.notify_all(); } if (state_->worker.joinable()) state_->worker.join(); }
void Subscription::debug_disconnect() { std::unique_lock lock(state_->mutex); if (!state_->connected) throw Error("Live WebSocket is not connected"); state_->command = State::Command::debug_disconnect; state_->command_done = false; state_->cv.wait_for(lock, std::chrono::seconds(2), [&]{ return state_->command_done; }); }
#ifdef CONVEX_CLIENT_TESTING
std::vector<Update> Subscription::pending_updates_for_test() { std::lock_guard lock(state_->mutex); return {state_->queue.begin(), state_->queue.end()}; }
#endif
}
